  ('fab27a3a-be69-4d4d-a27d-fb5ff0951599', $$Biologie$$, $$VWO$$, $$Blaasontsteking$$, $$VWO Biologie 2017-I$$),
  ('1dae6b03-9fbf-48db-9ed3-9adc4fa58ab6', $$Biologie$$, $$VWO$$, $$De jungle neemt netto koolstofdioxide op$$, $$VWO Biologie 2017-I$$),
  ('530a8c6c-7a18-4739-beca-ffda8c5351fe', $$Biologie$$, $$VWO$$, $$Gespierder door gendoping$$, $$VWO Biologie 2017-I$$),
  ('b06a1333-9da8-4051-991b-91021a29556d', $$Biologie$$, $$VWO$$, $$Plasje op Pinkpop levert P$$, $$VWO Biologie 2017-I$$),
  ('e443bf18-5e37-4b2b-9c00-d9815e4f7cd6', $$Biologie$$, $$VWO$$, $$Een bloedtransfusie voor je hond$$, $$VWO Biologie 2017-I$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('abace0ae-b4e6-4d95-8b2e-d2c5c0069ef2', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', $$forumbericht van Bregje over haar blaasontsteking$$,
   $$biologie-vwo-2017-i-blaasontsteking-context1.png$$,
   $$Op het internetforum van een weekblad stond het volgende bericht van Bregje: ''Vannacht werd ik wakker met een blaasontsteking en sindsdien zit ik bijna non-stop op het toilet. Vriend was zo lief om vanochtend een potje urine bij de doktersassistente te brengen voor een testje, maar vreemd genoeg was de urine helemaal schoon. Geen kuurtje dus, maar wel een afspraak bij de huisarts zometeen. Gelukkig een telefonisch consult, ik moet er niet aan denken om de deur uit te gaan. Hebben jullie dit wel eens gehad?''
Een ongecompliceerde blaasontsteking is een aandoening waarmee huisartsen vrijwel dagelijks worden geconfronteerd. In bijna alle gevallen gaat het om de darmbacterie Escherichia coli die zich aan het epitheel van de blaas hecht.$$, 'inline'),
  ('85297287-5acf-49e8-b9dc-d2928ea18685', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', $$doorsnede van het urogenitale stelsel van man en vrouw (afbeelding 1)$$,
   $$biologie-vwo-2017-i-blaasontsteking-context2.png$$,
   $$In afbeelding 1 is een doorsnede weergegeven van (delen van) het urogenitale stelsel van een vrouw en van een man. In de drie met een nummer aangegeven ruimtes is de aanwezigheid van micro-organismen normaal en veroorzaakt doorgaans geen klachten.
afbeelding 1: doorsnede van het urogenitale stelsel van een vrouw (links) en een man (rechts), met de nummers 1, 2 en 3 bij delen van de urinebuis waar micro-organismen normaal voorkomen.$$, 'inline'),
  ('06bc9265-9922-48d2-bbcf-9dcae2ecb2be', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', $$anatomische verschillen tussen mannen en vrouwen vergroten het risico op blaasontsteking bij vrouwen$$,
   $$biologie-vwo-2017-i-blaasontsteking-context3.png$$,
   $$Vrouwen hebben veel vaker een blaasontsteking dan mannen. Dit komt onder andere door verschillen in de bouw van de urogenitale organen van mannen en vrouwen.$$, 'inline'),
  ('b13c2df8-1334-4af6-80de-c2ae01a72bf9', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', $$forumadvies van Debbie: veel drinken en cranberrysap$$,
   $$biologie-vwo-2017-i-blaasontsteking-context4.png$$,
   $$Op het forum werden adviezen gegeven. Debbie: ''Veel drinken en cranberrysap drinken. Anders voor de zekerheid even vragen aan de huisarts of je urine gekweekt mag worden.''$$, 'inline'),
  ('23f23654-f6a4-4d49-97dc-509955d1c2a2', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', $$slijmlaag en adhesine als hechtingsmechanisme van E. coli (afbeelding 2)$$,
   $$biologie-vwo-2017-i-blaasontsteking-context5.png$$,
   $$De slijmlaag, geproduceerd door het epitheel van de blaas, vormt voor de meeste bacteriën een onneembare barrière. Sommige stammen van E. coli maken juist gebruik van deze beschermende laag. Deze bacteriën hebben haartjes met de bindstof adhesine, waarmee ze zich in de slijmlaag kunnen vasthechten (zie afbeelding 2). Als ze zo het epitheel van de blaas koloniseren, komt een acute ontstekingsreactie op gang.
afbeelding 2: schema van een bacterie met adhesinehaartjes die zich hechten aan de slijmlaag boven het membraan van een epitheelcel.$$, 'inline'),
  ('da0a47ee-0491-4971-8a4c-67510bb647dd', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', $$cranberrystoffen binden aan adhesine$$,
   $$biologie-vwo-2017-i-blaasontsteking-context6.png$$,
   $$Bepaalde stoffen in cranberry''s (veenbessen) kunnen zich hechten aan adhesine. Daarom wordt het gebruik van cranberrytabletten weleens aanbevolen tegen blaasontsteking.$$, 'inline'),
  ('f6bbe87c-818d-43f9-bc7b-0bf5e17e245b', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', $$diagnose via teststrookje op nitriet en leukocytenesterase$$,
   $$biologie-vwo-2017-i-blaasontsteking-context7.png$$,
   $$Als een vrouw de klachten van een blaasontsteking bij zichzelf herkent, kan verder onderzoek door de huisarts vaak achterwege blijven. Bij twijfel wordt een urinemonster onderzocht. Met een teststrookje wordt de aanwezigheid van nitriet en van leukocytenesterase (een enzym aanwezig in witte bloedcellen) in de urine onderzocht. Vaak is het niet nodig de urine op kweek te zetten om de ziekteverwekker te identificeren.$$, 'inline'),
  ('b3a9f183-a83e-4de1-a1e3-5dec98f2337b', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', $$nitrietvorming via dissimilatie van E. coli (afbeelding 3)$$,
   $$biologie-vwo-2017-i-blaasontsteking-context8.png$$,
   $$Het nitriet in het urinemonster is een product van de dissimilatie van E. coli. Deze bacterie is facultatief aeroob. Onder zuurstofrijke omstandigheden is zuurstof de elektronenacceptor bij de dissimilatie. Bij gebrek aan zuurstof, zoals in de blaas, gebruikt de bacterie nitraat als elektronenacceptor. In afbeelding 3 zijn de twee elektronentransportketens van E. coli weergegeven.
afbeelding 3: de aerobe elektronentransportketen van E. coli eindigt bij cytochroom o, waar elektronen worden overgedragen op zuurstof (3 H⁺ + ½ O₂ → H₂O). Bij de anaerobe keten ontbreekt deze laatste stap: de keten eindigt bij nitraatreductase, dat nitraat (NO₃⁻ + 2 H⁺) omzet in nitriet en water (NO₂⁻ + H₂O).$$, 'inline'),
  ('9b6b555d-883d-4083-a217-2e96d7249dfe', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', $$anaerobe dissimilatie levert minder energie per NADH op$$,
   $$biologie-vwo-2017-i-blaasontsteking-context9.png$$,
   $$E. coli kan in het anaerobe milieu van de blaas per NADH-molecuul minder energie vrijmaken dan onder aerobe omstandigheden.$$, 'inline'),
  ('74f0eb06-48d9-4eb7-8be0-acfeb3dedd80', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', $$leukocytenesterase is afkomstig van witte bloedcellen bij de ontstekingshaard$$,
   $$biologie-vwo-2017-i-blaasontsteking-context10.png$$,
   $$De leukocytenesterase in de urine is afkomstig van witte bloedcellen die als eerste naar de ontstekingshaard in de blaas gemigreerd zijn.$$, 'inline'),
  ('811ab98a-5755-4dc4-a203-4e5d6068f5fd', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', $$recept voor nitrofurantoïne, het eerste-keus-antibioticum (afbeelding 4)$$,
   $$biologie-vwo-2017-i-blaasontsteking-context11.png$$,
   $$Bregje: ''Ben net gebeld door de huisarts. Zij vertelde dat een beginnende blaasontsteking vaak nog niet zichtbaar is in de urine. Heb nu een kuurtje voor vijf dagen gekregen.''
Het eerste-keus-antibioticum voor de behandeling van een ongecompliceerde urineweginfectie bevat als werkzame stof nitrofurantoïne (C₈H₆N₄O₅).
afbeelding 4: recept voor nitrofurantoïne, 20 stuks, 4x per dag 1 capsule, met de instructie de kuur af te maken.$$, 'inline'),
  ('9607a5aa-63a0-4cc5-87ce-622dcb9c9672', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', $$farmacologische eigenschappen van nitrofurantoïne$$,
   $$biologie-vwo-2017-i-blaasontsteking-context12.png$$,
   $$Farmacologische eigenschappen van nitrofurantoïne zijn:
1 In de dunne darm wordt nitrofurantoïne vrijwel volledig geabsorbeerd.
2 Via het kapsel van Bowman komt nitrofurantoïne in de voorurine terecht.
3 In de nierbuisjes vindt secretie plaats van nitrofurantoïne.
4 In de nierbuisjes vindt re(ab)sorptie plaats van nitrofurantoïne.$$, 'inline'),
  ('2c9aa19b-3854-4cd0-a29f-1bcae7671a77', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', $$kuur van twintig tabletten moet worden afgemaakt$$,
   $$biologie-vwo-2017-i-blaasontsteking-context13.png$$,
   $$Nitrofurantoïne wordt voorgeschreven als een kuur van twintig tabletten. De patiënt moet de kuur afmaken om te voorkomen dat bacteriën resistent worden tegen het antibioticum.$$, 'inline'),
  ('fcd2c886-f6cb-441e-a200-ebd2934b70d3', '1dae6b03-9fbf-48db-9ed3-9adc4fa58ab6', $$tropische regenwouden leggen netto CO2 vast (afbeelding 1)$$,
   $$biologie-vwo-2017-i-jungle-co2-context1.png$$,
   $$Oude bossen kunnen een climaxstadium bereiken met een evenwicht tussen het aangroeien en afsterven van plantenmateriaal. Ongerepte tropische regenwouden (zie afbeelding 1) blijken echter jaarlijks 1,3 miljard ton aan koolstofdioxide vast te leggen. Dat wordt afgeleid uit onderzoek in Afrika en in het Amazonegebied. Een extra argument voor het beschermen van deze bossen.
afbeelding 1: foto van een ongerept tropisch regenwoud.$$, 'inline'),
  ('9441a18e-600c-43c7-9b15-336600fdd974', '1dae6b03-9fbf-48db-9ed3-9adc4fa58ab6', $$twee uitspraken over NPP en BPP in regenwouden die netto CO2 opnemen$$,
   $$biologie-vwo-2017-i-jungle-co2-context2.png$$,
   $$Naar aanleiding van het gegeven dat bepaalde regenwouden netto CO2 opnemen, worden twee uitspraken gedaan over de gemiddelde jaarlijkse netto en bruto primaire productie (NPP en BPP) in deze regenwouden:
1 De NPP is er ongeveer nul.
2 De BPP is er gelijk aan de NPP.$$, 'inline'),
  ('99339a84-05db-44f3-8a2c-dd446855097f', '1dae6b03-9fbf-48db-9ed3-9adc4fa58ab6', $$regenwouden herstellen mogelijk van eerdere verstoringen$$,
   $$biologie-vwo-2017-i-jungle-co2-context3.png$$,
   $$Dat de regenwouden netto veel CO2 vastleggen, ligt niet voor de hand. Misschien zijn deze regenwouden nog aan het herstellen van vroegere verstoringen, zoals bosbranden of ontginning voor de landbouw.$$, 'inline'),
  ('5716d2e4-3045-435c-a2d2-9912f8b66a95', '1dae6b03-9fbf-48db-9ed3-9adc4fa58ab6', $$veertigjarig onderzoek naar koolstofverandering in Afrikaanse proefvlakken (afbeelding 2)$$,
   $$biologie-vwo-2017-i-jungle-co2-context4.png$$,
   $$Een internationale onderzoeksgroep verzamelde bijna veertig jaar lang gegevens in 79 proefvlakken (van gemiddeld 2,1 ha) onverstoord regenwoud in tien Afrikaanse landen. De onderzoekers bepaalden onder andere de gemiddelde jaarlijkse verandering van opgeslagen koolstof (zie afbeelding 2).
afbeelding 2: histogram van het aantal proefvlakken tropisch regenwoud tegen de verandering in biomassa (10³ kg C per ha per jaar). De meeste proefvlakken laten een toename van de biomassa zien (een piek rond +1); een klein aantal proefvlakken laat een afname zien (negatieve waarden).$$, 'inline'),
  ('03e59a02-e8ab-4d5a-9f38-8d867ec0a450', '1dae6b03-9fbf-48db-9ed3-9adc4fa58ab6', $$twee beweringen over de resultaten in afbeelding 2$$,
   $$biologie-vwo-2017-i-jungle-co2-context5.png$$,
   $$Twee beweringen over de in afbeelding 2 weergegeven resultaten zijn:
1 In de onderzochte bossen neemt de totale biomassa gemiddeld genomen toe.
2 Ruim 15% van de proefvlakken geeft netto CO2 af aan de atmosfeer.$$, 'inline'),
  ('6c0a82f0-9453-4152-8c13-46f83eb244af', '1dae6b03-9fbf-48db-9ed3-9adc4fa58ab6', $$kap-en-brandlandbouw als vermeend duurzame landbouwmethode$$,
   $$biologie-vwo-2017-i-jungle-co2-context6.png$$,
   $$De oorspronkelijke landbouwmethode van inheemse volken heeft een vast patroon: een stukje regenwoud kappen en platbranden en er een tijdlang gewassen verbouwen. Na uitputting van de bodem trekken de mensen verder en beginnen elders opnieuw.
Er wordt wel beweerd dat deze werkwijze, in het kader van klimaatverandering door het versterkt broeikaseffect, een duurzame vorm van landbouw bedrijven is.$$, 'inline'),
  ('5dbd5335-14e1-4d05-99ed-6c161e8bfd41', '1dae6b03-9fbf-48db-9ed3-9adc4fa58ab6', $$gegevens nodig om het effect op het broeikaseffect te beoordelen$$,
   $$biologie-vwo-2017-i-jungle-co2-context7.png$$,
   $$Om te beoordelen of de oorspronkelijke landbouwmethode daadwerkelijk het versterkt broeikaseffect kan tegengaan, zijn onder andere gegevens nodig over opname en afgifte van CO2.$$, 'inline'),
  ('7fdd4556-4b47-4842-8e7b-b7057c109fcd', '1dae6b03-9fbf-48db-9ed3-9adc4fa58ab6', $$droogteperiodes in het Amazonegebied verminderden de fotosynthese$$,
   $$biologie-vwo-2017-i-jungle-co2-context8.png$$,
   $$Het is onduidelijk of tropische regenwouden in de toekomst ook nog netto CO2 blijven vastleggen. In 2005 en 2010 registreerden Amerikaanse onderzoekers een droge periode in het Amazone-regenwoud. Tijdens deze droogteperiode vond er minder fotosynthese plaats.$$, 'inline'),
  ('bcbaafb5-2854-4b18-96f2-522054f539f1', '1dae6b03-9fbf-48db-9ed3-9adc4fa58ab6', $$droogte vermindert de gaswisseling in planten$$,
   $$biologie-vwo-2017-i-jungle-co2-context9.png$$,
   $$De verminderde fotosynthese wordt onder meer veroorzaakt doordat er bij droogte minder gaswisseling in planten mogelijk is.$$, 'inline'),
  ('7ac3dc23-7320-4ee9-9acb-4646bc40650c', '530a8c6c-7a18-4739-beca-ffda8c5351fe', $$gendoping als experimentele techniek om spiermassa te vergroten$$,
   $$biologie-vwo-2017-i-gendoping-context1.png$$,
   $$Het overdragen van genetisch materiaal naar menselijke cellen voor de behandeling van ziektes bevindt zich nog in een experimenteel stadium. Deze techniek zou ook gebruikt kunnen worden als gendoping bij sporters. Het is inmiddels al gelukt om muizen door gendoping supergespierd te maken.$$, 'inline'),
  ('fde6618c-60c0-4119-bd89-df307df75cf5', '530a8c6c-7a18-4739-beca-ffda8c5351fe', $$myostatine remt satellietcellen; een jongetje met een gemuteerd myostatine-gen (afbeelding 1)$$,
   $$biologie-vwo-2017-i-gendoping-context2.png$$,
   $$Een goede kandidaat voor gendoping is een gemuteerd gen voor myostatine. Myostatine remt de activatie van satellietcellen. Dat zijn cellen in de spieren die kunnen delen en differentiëren naar myoblasten, de voorlopers van spiervezels. Onder leiding van Dr. Schuelke, kinderneuroloog bij het UMC te Berlijn, is onderzoek gedaan naar de ontwikkeling van spiermassa bij kinderen. Aan een Duits jongetje met een gemuteerd myostatine-gen is te zien wat het resultaat van deze mutatie is (afbeelding 1).
afbeelding 1: foto van een klein jongetje dat met gemak een halterstang optilt.$$, 'inline'),
  ('8ad3cd26-c3e2-4041-bbd4-b2a6b5ccd2d3', '530a8c6c-7a18-4739-beca-ffda8c5351fe', $$familiestamboom en restrictie-enzymanalyse van het myostatine-gen (afbeelding 2 en 3)$$,
   $$biologie-vwo-2017-i-gendoping-context3.png$$,
   $$Schuelke onderzocht de familiestamboom van het jongetje (nummer III-1 in afbeelding 2). Zowel de opa van het jongetje als twee ooms waren bijzonder sterk en gespierd. Ook moeder oogde gespierd, maar niet zo gespierd als haar zoon. Over de vader van het jongetje is dit niet bekend. Voor genetisch onderzoek was alleen materiaal van het jongetje en zijn moeder beschikbaar. Van beiden werd een fragment van 166 basenparen van het myostatine-gen vermenigvuldigd met PCR. Een restrictie-enzym werd gebruikt om de mutatie op te sporen. Alleen in het wild-type gen knipt het enzym dit fragment in twee delen: een van 135 bp en een van 31 bp. Het mutantgen wordt door dit restrictie-enzym niet geknipt. Met gel-elektroforese werden de fragmenten op lengte gescheiden. Het resultaat van de elektroforese is weergegeven in afbeelding 3. Kleine fragmenten van 31 bp zijn hierin niet te zien.
afbeelding 2: familiestamboom over drie generaties (I, II, III); gevulde symbolen zijn bijzonder sterk en gespierd (waaronder II-3, II-4 (vader, onbekend, met vraagteken), II-5, moeder II-3 die getrouwd is met een man met onbekend fenotype (II-onbekend), en het jongetje III-1, aangegeven met een sterretje).
afbeelding 3: gel-elektroforesefoto met banen voor het jongetje, de moeder, een controle (wel geknipt) en een controle (niet geknipt); bij het jongetje is één band te zien op de hoogte van het ongeknipte fragment (~166 bp), bij de moeder twee banden (~166 bp en ~135 bp).$$, 'inline'),
  ('27f900de-5a5c-4516-9dbd-c8faa3eb6c33', '530a8c6c-7a18-4739-beca-ffda8c5351fe', $$uit stamboom en genetisch onderzoek is de overerving van de gespierdheid af te leiden$$,
   $$biologie-vwo-2017-i-gendoping-context4.png$$,
   $$Uit de familiestamboom, gecombineerd met het genetisch onderzoek, is af te leiden hoe gespierdheid als gevolg van een mutant-myostatine-gen overerft.$$, 'inline'),
  ('ad10ae93-6b43-4bb3-a8ff-ec95e0a88fc3', '530a8c6c-7a18-4739-beca-ffda8c5351fe', $$RNA-interferentie kan de myostatine-genexpressie verminderen (afbeelding 4)$$,
   $$biologie-vwo-2017-i-gendoping-context5.png$$,
   $$In theorie is het mogelijk het myostatine-gen bij een sporter uit te schakelen en hem zo supergespierd te maken. Een manier om het gen ''knock down'' te maken, is door RNA-interferentie (RNAi). De expressie van het gen voor myostatine wordt daardoor verminderd. In afbeelding 4 is het proces van RNA-interferentie, waarbij gebruik wordt gemaakt van een plasmidevector, schematisch weergegeven.
afbeelding 4: (1) via een vector komt een genconstruct in de kern van een cel; (2) op basis hiervan ontstaat mRNA met een ''sense''- en ''antisense''-deel die een haarspeld-RNA (shRNA) vormen; (3) het enzym dicer bewerkt het shRNA tot een stukje interfererend dubbelstrengs RNA (siRNA); (4) dit siRNA bindt aan eiwitcomplex RISC (RNA-induced silencing complex) en wordt enkelstrengs; (5) het antisense-RNA in het geactiveerde RISC bindt aan complementair rijp mRNA, waarna dit wordt gesplitst en vervolgens afgebroken.$$, 'inline'),
  ('a8fa4cff-2112-40d6-91da-9987aea06586', '530a8c6c-7a18-4739-beca-ffda8c5351fe', $$vier mogelijke processen bij RNA-interferentie van het myostatine-gen$$,
   $$biologie-vwo-2017-i-gendoping-context6.png$$,
   $$Door RNA-interferentie kan de myostatineproductie in satellietcellen verminderen.
Vier processen zijn:
1 transcriptie van het genconstruct
2 transcriptie van het myostatine-gen
3 translatie van het mRNA op basis van het genconstruct
4 translatie van het myostatine-mRNA$$, 'inline'),
  ('f7f1286a-7e62-43c3-92e3-504eb4a969f5', '530a8c6c-7a18-4739-beca-ffda8c5351fe', $$onderzoek bij muizen met knock-downfragmenten K1 en K2$$,
   $$biologie-vwo-2017-i-gendoping-context7.png$$,
   $$Een groep onderzoekers uit Japan en Indonesië heeft deze manier van gendoping onderzocht bij gezonde muizen. Ze kozen twee fragmenten van het myostatine-gen als potentiële knock-downsequenties (K1 en K2). Van elk fragment werd dubbelstrengs DNA geconstrueerd. Dat werd ingebouwd in een plasmide en − verpakt in liposomen − ingespoten in de beenspieren van muizen.$$, 'inline'),
  ('4c57edd3-1fba-4a80-933e-9cca91185163', '530a8c6c-7a18-4739-beca-ffda8c5351fe', $$knock-downfragmenten zijn geconstrueerd uit delen van exons$$,
   $$biologie-vwo-2017-i-gendoping-context8.png$$,
   $$Voor de constructie van knock-down-DNA-fragmenten van het myostatine-gen zijn delen van exons gebruikt.$$, 'inline'),
  ('72c625ef-ffa6-4bd8-a01f-1b87125578cc', '530a8c6c-7a18-4739-beca-ffda8c5351fe', $$haarspeld-RNA en de sense-nucleotidenvolgorde van K2 (afbeelding 5)$$,
   $$biologie-vwo-2017-i-gendoping-context9.png$$,
   $$Een haarspeld-RNA (shRNA) ontstaat als in het mRNA een sense- en een antisense-sequentie voorkomen (zie afbeelding 5) die complementair zijn.
afbeelding 5: schema van een haarspeld-RNA (shRNA) met een dubbelstrengs sense/antisense-stengel en een enkelstrengse lus, met de 5''- en 3''-uiteinden aangegeven.
Een deel van de coderende streng van DNA-fragment K2 uit het myostatine-gen dat codeert voor het sense-deel van het shRNA heeft als nucleotidenvolgorde:
5'' - AAATACCAGTGCCTTTTTTT - 3''$$, 'inline'),
  ('36dfa527-d22e-4752-bb1f-39fe160a11c2', '530a8c6c-7a18-4739-beca-ffda8c5351fe', $$promotors P en Q in het K2-genconstruct (afbeelding 6)$$,
   $$biologie-vwo-2017-i-gendoping-context10.png$$,
   $$Naast de sense- en antisense-DNA-sequenties bevinden zich ook promotors in de genconstructen. In afbeelding 6 is de coderende streng van een deel van het genconstruct K2 getekend. Twee plaatsen zijn aangegeven met P en Q.
afbeelding 6: schema van een deel van de coderende streng van genconstruct K2 met twee aangegeven plaatsen, P en Q.$$, 'inline'),
  ('1cd28448-90fa-4b64-a475-32de76c3e79b', '530a8c6c-7a18-4739-beca-ffda8c5351fe', $$geen sporen van gendoping in bloed, wel tijdelijk in spierweefsel$$,
   $$biologie-vwo-2017-i-gendoping-context11.png$$,
   $$De onderzoekers zochten in het bloed van de muizen naar sporen van de gendoping, maar ze vonden niets. In de eerste vier weken na de behandeling kon het genconstruct nog wel in spierweefsel worden aangetoond, daarna niet meer. Om dit type gendoping bij sporters aan te tonen zou dus ten minste elke maand een spierbiopt genomen moeten worden. Een dergelijke belastende methode zal echter niet worden toegepast. De Nederlandse Dopingautoriteit adviseert om een detectiemethode op basis van ''proteomics''-technieken te ontwikkelen; daarmee wordt regelmatig het eiwitprofiel in een bloedmonster van de sporter bepaald.$$, 'inline'),
  ('33d4feb3-9c38-4f88-a823-2198f3c81e10', 'b06a1333-9da8-4051-991b-91021a29556d', $$fosfaatprobleem en een vereenvoudigde fosfaatkringloop (afbeelding 1)$$,
   $$biologie-vwo-2017-i-fosfaatkringloop-context1.png$$,
   $$In 2011 is tijdens het Pinkpopfestival de urine van mannelijke bezoekers ingezameld om het daarin aanwezige fosfaat terug te winnen en om te zetten in kunstmest. Het experiment werd uitgevoerd in samenwerking met SaNiPhos, een urineverwerkingsfabriek.
De wereld kampt met een fosfaatprobleem: lokaal veroorzaakt de mens ophopingen van fosfaat met bijbehorende milieuproblemen, terwijl op wereldschaal voor de landbouw juist een tekort aan fosfaat dreigt. Dit tekort brengt het risico van een wereldvoedselprobleem met zich mee. Alle organismen hebben namelijk het element fosfor nodig.
In afbeelding 1 is een vereenvoudigde fosfaatkringloop weergegeven.
afbeelding 1: schema van de fosfaatkringloop met de compartimenten landplanten, waterplanten, landdieren, waterdieren, landbouw, kunstmest, fosfaatwinning, sedimentatie, fosfaat in bodem en fosfaat in water, verbonden door pijlen die de fosfaatstromen tussen de compartimenten weergeven.$$, 'inline'),
  ('9c4477a1-da5f-49d9-bcd3-2ce788623c25', 'b06a1333-9da8-4051-991b-91021a29556d', $$een extra pijl voor de fosfaatstroom van SaNiPhos$$,
   $$biologie-vwo-2017-i-fosfaatkringloop-context2.png$$,
   $$De fosfaatstroom die ontstaat door het initiatief van SaNiPhos, kan aan deze weergave van de kringloop toegevoegd worden door een extra pijl te plaatsen tussen twee compartimenten.$$, 'inline'),
  ('499ef18d-47a9-4db9-aa5b-1df1fb923dec', 'b06a1333-9da8-4051-991b-91021a29556d', $$de kringloop is niet compleet voor landdieren$$,
   $$biologie-vwo-2017-i-fosfaatkringloop-context3.png$$,
   $$De kringloop in afbeelding 1 is niet compleet. De landdieren bijvoorbeeld, betrekken fosfor uit meer compartimenten dan alleen die van de landplanten en de landbouw.$$, 'inline'),
  ('28a30366-2215-4c5d-90a1-714f3bc920b9', 'b06a1333-9da8-4051-991b-91021a29556d', $$fosfaatverrijking van oppervlaktewater veroorzaakte vissterfte$$,
   $$biologie-vwo-2017-i-fosfaatkringloop-context4.png$$,
   $$In de vorige eeuw was verrijking van het oppervlaktewater met fosfaat, onder andere uit wasmiddelen, een groot probleem. Het leidde plaatselijk tot vissterfte in sloten.$$, 'inline'),
  ('3fd5ac87-65d4-4961-bda3-9ce8996edfc7', 'b06a1333-9da8-4051-991b-91021a29556d', $$fosfor wordt gebruikt bij stofwisselingsreacties in planten$$,
   $$biologie-vwo-2017-i-fosfaatkringloop-context5.png$$,
   $$In planten wordt het element fosfor onder andere gebruikt bij stofwisselingsreacties.$$, 'inline'),
  ('95c95be0-0a19-46d6-9964-89592d427bc7', 'b06a1333-9da8-4051-991b-91021a29556d', $$drie structuren van plantaardige cellen$$,
   $$biologie-vwo-2017-i-fosfaatkringloop-context6.png$$,
   $$Structuren van plantaardige cellen zijn:
1 celmembraan
2 chromosomen
3 golgi-systeem$$, 'inline'),
  ('5e1db870-3202-4cee-9f6a-3b8a6e758721', 'b06a1333-9da8-4051-991b-91021a29556d', $$reabsorptie van fosfaat via NaPi-cotransporters, gereguleerd door PTH$$,
   $$biologie-vwo-2017-i-fosfaatkringloop-context7.png$$,
   $$Slechts een deel van het fosfaat dat in de nieren uit het bloed gefiltreerd wordt, komt uiteindelijk in de urine terecht. Het grootste gedeelte wordt gereabsorbeerd.
De mate van reabsorptie van fosfaat (Pi) in een nierbuisje wordt mede geregeld door het aantal NaPi-transporteiwitten in het celmembraan van de epitheelcellen. Inbouw van deze NaPi-cotransporters aan de lumenzijde van de cellen wordt gestimuleerd door een lage fosfaatconcentratie in het bloed; onder invloed van het parathormoon (PTH) trekken deze cotransporters zich terug en worden ze tijdelijk opgeslagen in het cytoplasma.
In afbeelding 2 is schematisch weergegeven hoe de reabsorptie van fosfaat in een nierbuisje verloopt.$$, 'inline'),
  ('e752b5c0-03c3-4815-a0ac-3d75ecc2c329', 'b06a1333-9da8-4051-991b-91021a29556d', $$schema van fosfaatreabsorptie in een nierbuisje (afbeelding 2)$$,
   $$biologie-vwo-2017-i-fosfaatkringloop-context8.png$$,
   $$afbeelding 2: schema van een nierbuisje-epitheelcel tussen het lumen van het nierbuisje en het bloed. Aan de lumenzijde brengen NaPi-cotransporters Na⁺ en Pi de cel in; aan de bloedzijde verlaat Pi de cel via passief transport, en houdt een Na/K-pomp (3 Na⁺ eruit, 2 K⁺ erin) de natriumgradiënt in stand die de NaPi-cotransporters aandrijft.$$, 'inline'),
  ('85115c73-70c9-4c41-a02b-76ab7feabfcb', 'b06a1333-9da8-4051-991b-91021a29556d', $$afgifte van parathormoon hangt af van de calciumconcentratie in het bloed$$,
   $$biologie-vwo-2017-i-fosfaatkringloop-context9.png$$,
   $$De afgifte van het parathormoon staat onder invloed van de calciumconcentratie in het bloed.$$, 'inline'),
  ('70a7348b-3f00-49b6-8b13-64252d494a17', 'b06a1333-9da8-4051-991b-91021a29556d', $$SaNiPhos verwerkt ook stikstof (ureum) tot kunstmest$$,
   $$biologie-vwo-2017-i-fosfaatkringloop-context10.png$$,
   $$Niet alleen het fosfaat wordt door SaNiPhos uit de verzamelde plasjes verwerkt tot kunstmest, maar ook de stikstof.$$, 'inline'),
  ('de8250f4-b525-4615-8d29-5944713f19ed', 'e443bf18-5e37-4b2b-9c00-d9815e4f7cd6', $$Max, een boxer met acute hemolytische anemie door uienvergiftiging (afbeelding 1)$$,
   $$biologie-vwo-2017-i-bloedtransfusie-hond-context1.png$$,
   $$Sophia belde in paniek haar dierenarts. Haar hond Max, een levendige boxer (zie afbeelding 1), was plotseling in elkaar gezakt en kwam niet meer overeind. Dierenarts Yin onderzocht het bloed van de hond en daaruit bleek dat Max acute hemolytische anemie had, een vorm van bloedarmoede. De oorzaak was een zakje gedroogde uien dat Max een paar dagen daarvoor had leeggegeten. Uien bevatten stoffen die bij honden de rode bloedcellen beschadigen.
afbeelding 1: foto van Max, een boxer.$$, 'inline'),
  ('799441fe-2be7-4a4f-8d0e-68b3f2b74a30', 'e443bf18-5e37-4b2b-9c00-d9815e4f7cd6', $$EPO wordt vaak toegediend om anemie te verhelpen$$,
   $$biologie-vwo-2017-i-bloedtransfusie-hond-context2.png$$,
   $$Om anemie te verhelpen wordt vaak het hormoon EPO toegediend.$$, 'inline'),
  ('4a2c9ff4-3830-4331-84f8-3974deab02e6', 'e443bf18-5e37-4b2b-9c00-d9815e4f7cd6', $$dierenarts Yin kiest voor een bloedtransfusie in plaats van EPO$$,
   $$biologie-vwo-2017-i-bloedtransfusie-hond-context3.png$$,
   $$Max krijgt echter geen (honden-)EPO toegediend; dierenarts Yin kiest voor een bloedtransfusie.$$, 'inline'),
  ('82065ed1-f33e-4427-9d55-3ca7da56be91', 'e443bf18-5e37-4b2b-9c00-d9815e4f7cd6', $$DEA-bloedgroepantigenen bij honden en de frequenties in Nederland (tabel 1)$$,
   $$biologie-vwo-2017-i-bloedtransfusie-hond-context4.png$$,
   $$Net als bij de mens is een bloedtransfusie met willekeurig bloed gevaarlijk voor een hond door de aanwezigheid van bloedgroep-antigenen. Bij honden spelen echter andere bloedgroep-antigenen een rol. Deze worden aangeduid met DEA (Dog Erythrocyte Antigens).
Het antigeen waarmee met name rekening gehouden moet worden bij transfusies is DEA1. Daarvan bestaan drie allelen: DEA1.1, DEA1.2 en DEA1.3, die elk coderen voor een andere variant van het antigeen DEA1. Allel DEA1.1 is dominant over beide andere allelen, allel DEA1.2 is dominant over DEA1.3. Honden die geen DEA1-antigeen hebben, zijn DEA1-negatief.
De frequentie van de verschillende bloedgroepen bij honden in Nederland is weergegeven in tabel 1.
tabel 1: frequentie DEA1.1 42%, DEA1.2 20%, DEA1.3 zeer zeldzaam, DEA1-negatief 38%.
Honden hebben normaliter geen antistoffen tegen DEA1 in hun bloed. Wanneer echter een DEA1-negatieve hond een transfusie krijgt met DEA1.1-bloed, ontstaat er een snelle sensibilisatie (gevoeligheid voor het antigeen), waarbij antistoffen tegen het antigeen gevormd worden. Krijgt zo''n hond een tweede maal een transfusie met DEA1.1-bloed, dan ontstaat er een ernstige afweerreactie. Bij andere combinaties van bloedgroepen is de afweerreactie niet gevaarlijk.$$, 'inline'),
  ('3372b594-9bd6-4a88-aa2d-51cef58963f1', 'e443bf18-5e37-4b2b-9c00-d9815e4f7cd6', $$vroeger werd hondenbloed niet getypeerd, met risico op sensibilisatie$$,
   $$biologie-vwo-2017-i-bloedtransfusie-hond-context5.png$$,
   $$In het verleden was het niet gebruikelijk om hondenbloed te typeren. Zo kon het gebeuren dat een hond na de eerste transfusie gesensibiliseerd raakte en door een tweede transfusie stierf.$$, 'inline'),
  ('ab7d53e3-616d-4b24-8063-e16e145ab755', 'e443bf18-5e37-4b2b-9c00-d9815e4f7cd6', $$Max krijgt de transfusie via een rechtervoorpootader; risico bij een stolsel$$,
   $$biologie-vwo-2017-i-bloedtransfusie-hond-context6.png$$,
   $$Max krijgt een bloedtransfusie via een rechtervoorpootader. Een mogelijk gevolg van een afweerreactie na een bloedtransfusie is klontering van rode bloedcellen. De ernst van het gezondheidsrisico hangt samen met de plaats waar zo''n stolsel ontstaat.$$, 'inline'),
  ('b7ca2fc2-9b79-4ee3-bf89-b16e64f874ac', 'e443bf18-5e37-4b2b-9c00-d9815e4f7cd6', $$DEA1-fenotypefrequenties bij hondenrassen in Brazilië (tabel 2)$$,
   $$biologie-vwo-2017-i-bloedtransfusie-hond-context7.png$$,
   $$Wetenschappers van de universiteit van São Paulo onderzochten het voorkomen van de DEA1-fenotypes bij verschillende hondenrassen en bij bastaardhonden (geen zuiver ras) in Brazilië. Er blijken grote verschillen in bloedgroepfrequenties te bestaan tussen deze groepen.
De resultaten van het onderzoek zijn weergegeven in tabel 2.
tabel 2: aantal honden, % DEA1.1, % DEA1.2 en % DEA1-negatief per groep: bastaard (73 honden: 46,6% / 42,5% / 11%), boxer (5 honden: 20% / 60% / 20%), cocker spaniël (14 honden: 71,4% / 21,4% / 7,14%), Deense dog (6 honden: 83,3% / 16,7% / 0%), Duitse herder (19 honden: 36,8% / 63,2% / 0%), rottweiler (7 honden: 42,9% / 42,9% / 14,3%).$$, 'inline'),
  ('5554c4a0-71d1-462a-b741-ea1c1a0a3ad5', 'e443bf18-5e37-4b2b-9c00-d9815e4f7cd6', $$meer gegevens nodig voor een goede kansberekening bij Braziliaanse boxers$$,
   $$biologie-vwo-2017-i-bloedtransfusie-hond-context8.png$$,
   $$De kans dat bij een willekeurige Braziliaanse boxer sensibilisatie optreedt na bloedtransfusie met bloed van een andere boxer of van een willekeurige andere hond uit Brazilië, kan op grond van alleen deze resultaten (tabel 2) niet goed bepaald worden. Daarvoor zijn meer gegevens nodig.$$, 'inline'),
  ('96657adc-f1d3-429e-baaf-561f4175921d', 'e443bf18-5e37-4b2b-9c00-d9815e4f7cd6', $$Braziliaanse boxergegevens zijn niet bruikbaar voor Europese boxers$$,
   $$biologie-vwo-2017-i-bloedtransfusie-hond-context9.png$$,
   $$Boxers zijn met mensen mee vanuit Europa naar Brazilië gemigreerd. De Braziliaanse gegevens (in tabel 2) zijn niet goed bruikbaar voor een risico-inschatting van een bloedtransfusie voor boxers in Europa. De bloedgroepfrequenties van de verschillende rashonden in Brazilië zijn namelijk anders dan die van dezelfde rassen in Nederland.$$, 'inline'),
  ('69f1d254-d64b-40b7-a1dc-8dc8fe1b4d4a', 'e443bf18-5e37-4b2b-9c00-d9815e4f7cd6', $$ID-Gel Test om Max op DEA1.1 te typeren (afbeelding 2)$$,
   $$biologie-vwo-2017-i-bloedtransfusie-hond-context10.png$$,
   $$Het is niet bekend of Max al eerder een bloedtransfusie heeft gehad. Om te voorkomen dat Max door een transfusie sensibiliseert, wordt zijn bloed vooraf getypeerd op DEA1.1 met een ''ID-Gel Test'', bestaande uit zes testbuisjes. De gel van de drie DEA1.1-buisjes bevat antistoffen tegen DEA1.1. De gel van de drie ctl-buisjes niet: dat zijn de controlebuisjes. Voor de test worden twee bloedmonsters van Max (60147) op de gel aangebracht, en ter vergelijking de getypeerde bloedmonsters van twee andere honden (60160 en 60125). Alle buisjes worden vervolgens gecentrifugeerd. Intacte rode bloedcellen zullen hierdoor naar de bodem zakken, terwijl samengeklonterde rode bloedcellen boven in de gel blijven. Het resultaat van deze test is weergegeven in afbeelding 2.
afbeelding 2: zes testbuisjes (DEA1.1 en ctl) voor Max en twee andere honden; bij Max is in beide buisjes (DEA1.1 en ctl) een band bloedcellen te zien onderin de gel (geen klontering).$$, 'inline'),
  ('157b54b3-aad0-4728-a276-6a74aa9b1957', 'e443bf18-5e37-4b2b-9c00-d9815e4f7cd6', $$de test bepaalt de bloedgroep van Max en de geschikte transfusie$$,
   $$biologie-vwo-2017-i-bloedtransfusie-hond-context11.png$$,
   $$Uit de test blijkt of Max DEA1.1-positief of DEA1-negatief is en welke bloedtransfusie geschikt is voor Max, rekening houdend met mogelijk optredende sensibilisatie in de toekomst.$$, 'inline'),
  ('6f12b9c8-abb3-4621-a35c-cd2ef474c2ee', 'e443bf18-5e37-4b2b-9c00-d9815e4f7cd6', $$berekening van de benodigde hoeveelheid donorbloed voor Max$$,
   $$biologie-vwo-2017-i-bloedtransfusie-hond-context12.png$$,
   $$Om te bepalen hoeveel bloed bij Max moet worden toegediend, wordt Max gewogen: hij weegt ruim 30 kg. Daarmee berekent de dierenarts het bloedvolume van Max. Een hond bezit gemiddeld 85 ml bloed per kilo lichaamsgewicht. Dr. Yin bepaalt ook de hematocrietwaarde (Ht) van Max. Dat is het volumedeel rode bloedcellen in het bloed. Bij een gezonde hond ligt de Ht tussen de 0,4 en 0,6; bij Max is de waarde slechts 0,2. Het donorbloed heeft een Ht van 0,45.
De benodigde hoeveelheid bloed wordt bepaald met behulp van de formule:
hoeveelheid donorbloed = (bloedvolume ontvanger x (gewenste Ht − Ht ontvanger)) / Ht donor
De dierenarts heeft donorbloed op voorraad in zakjes van 1 liter, 0,5 liter, 200 milliliter en 100 milliliter.$$, 'inline'),
  ('50bcd3c0-3185-4707-aaee-43fed6420468', 'e443bf18-5e37-4b2b-9c00-d9815e4f7cd6', $$kunstbloed met oxyglobine en runderserumeiwitten als alternatief$$,
   $$biologie-vwo-2017-i-bloedtransfusie-hond-context13.png$$,
   $$Dierenartsen gebruiken voor bloedtransfusies steeds vaker kunstbloed, met daarin oxyglobine als O2-drager. Oxyglobine wordt gemaakt door minimaal twee hemoglobinemoleculen aan elkaar te koppelen. Kunstbloed bestaat verder uit een fysiologische zoutoplossing met albumine en andere serumeiwitten van koeien. Daardoor heeft het kunstbloed ook de juiste colloïd-osmotische waarde.$$, 'inline'),
  ('af059a11-5f76-4125-8b7f-d77675b4e830', 'e443bf18-5e37-4b2b-9c00-d9815e4f7cd6', $$te weinig albumine in kunstbloed kan oedeem veroorzaken$$,
   $$biologie-vwo-2017-i-bloedtransfusie-hond-context14.png$$,
   $$Als kunstbloed met onvoldoende albumine wordt gebruikt, kan oedeem (zwelling van weefsels) ontstaan bij de hond die de transfusie heeft gekregen.$$, 'inline'),
  ('8bbafbe4-b121-421c-89de-3e698d2848f8', 'e443bf18-5e37-4b2b-9c00-d9815e4f7cd6', $$kunstbloed kan een afweerreactie oproepen; mogelijk immuunsuppressie nodig$$,
   $$biologie-vwo-2017-i-bloedtransfusie-hond-context15.png$$,
   $$Een transfusie met kunstbloed lijkt een goede oplossing voor de bloedarmoede van Max, maar na toedienen van kunstbloed kan het wel nodig zijn om hem te behandelen met medicijnen die het immuunsysteem onderdrukken.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('9cb6c17b-a69f-47ad-b132-17adfa9c6a6e', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', 1,
   '[{"domain": "Orgaan- en organismeniveau", "subdomain": "Stofwisseling van het organisme"}]'::jsonb,
   '["urinewegen", "anatomie", "plasbuislengte", "infectierisico"]'::jsonb,
   $$Een anatomisch verschil tussen mannen en vrouwen noemen dat verklaart waarom vrouwen vaker een blaasontsteking krijgen.$$,
   $$biologie-vwo-2017-i-blaasontsteking-vraag1.png$$, $$− Noteer zo''n anatomisch verschil.
− Verklaar aan de hand daarvan waardoor de kans op een blaasontsteking bij vrouwen groter is dan bij mannen.$$, array['abace0ae-b4e6-4d95-8b2e-d2c5c0069ef2','85297287-5acf-49e8-b9dc-d2928ea18685','06bc9265-9922-48d2-bbcf-9dcae2ecb2be']::uuid[]),
  ('58f5659e-055e-4c34-8c22-41a979694e70', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', 2,
   '[{"domain": "Orgaan- en organismeniveau", "subdomain": "Stofwisseling van het organisme"}]'::jsonb,
   '["diurese", "bacteriën wegspoelen", "vochtinname", "urineproductie"]'::jsonb,
   $$Verklaren waarom veel drinken bacteriën helpt wegspoelen uit de blaas.$$,
   $$biologie-vwo-2017-i-blaasontsteking-vraag2.png$$, $$Waarom is het een goed advies om veel te drinken als je een blaasontsteking hebt?$$, array['b13c2df8-1334-4af6-80de-c2ae01a72bf9']::uuid[]),
  ('080c0f34-0071-4ddf-8987-edaf328148d4', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', 3,
   '[{"domain": "Molecuul- en Celniveau", "subdomain": "Moleculaire en cellulaire interactie"}]'::jsonb,
   '["adhesine", "receptorbinding", "bacteriële adhesie", "preventie versus genezing"]'::jsonb,
   $$Uitleggen dat cranberrystoffen adhesine blokkeren, waardoor nieuwe hechting wordt voorkomen maar reeds gehechte bacteriën niet loslaten.$$,
   $$biologie-vwo-2017-i-blaasontsteking-vraag3.png$$, $$− Verklaar waardoor het gebruik van cranberrytabletten preventief goed zou kunnen werken tegen blaasontsteking,
− maar dat het gebruik ervan ter genezing van blaasontsteking minder effectief zal zijn.$$, array['23f23654-f6a4-4d49-97dc-509955d1c2a2','da0a47ee-0491-4971-8a4c-67510bb647dd']::uuid[]),
  ('2975f790-822f-4b59-b68a-a65572bfed67', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', 4,
   '[{"domain": "Molecuul- en Celniveau", "subdomain": "Stofwisseling van de cel"}]'::jsonb,
   '["elektronentransportketen", "anaerobe dissimilatie", "nitraat als elektronenacceptor", "ATP-opbrengst"]'::jsonb,
   $$Aan de hand van het elektronentransportschema verklaren waarom anaerobe dissimilatie per NADH minder energie oplevert dan aerobe dissimilatie.$$,
   $$biologie-vwo-2017-i-blaasontsteking-vraag4.png$$, $$Leg dit uit aan de hand van een gegeven in afbeelding 3.$$, array['b3a9f183-a83e-4de1-a1e3-5dec98f2337b','9b6b555d-883d-4083-a217-2e96d7249dfe']::uuid[]),
  ('17096de6-b4fc-41f4-b3c9-5dfc90991552', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', 5,
   '[{"domain": "Orgaan- en organismeniveau", "subdomain": "Afweer van het organisme"}]'::jsonb,
   '["leukocytenesterase", "fagocyten", "aangeboren afweer", "ontstekingsreactie"]'::jsonb,
   $$Bepalen welk type witte bloedcel als eerste naar een ontstekingshaard migreert.$$,
   $$biologie-vwo-2017-i-blaasontsteking-vraag5.png$$, $$Welk type witte bloedcellen is dit?
A cytotoxische T-cellen
B fagocyten
C T-helpercellen
D plasmacellen$$, array['f6bbe87c-818d-43f9-bc7b-0bf5e17e245b','74f0eb06-48d9-4eb7-8be0-acfeb3dedd80']::uuid[]),
  ('a564a5d3-b3f6-4991-89b9-d03188eddba0', 'fab27a3a-be69-4d4d-a27d-fb5ff0951599', 6,
   '[{"domain": "Orgaan- en organismeniveau", "subdomain": "Stofwisseling van het organisme"}]'::jsonb,
   '["ultrafiltratie", "secretie", "reabsorptie", "nierbuisje", "farmacokinetiek"]'::jsonb,
   $$Beoordelen welke farmacokinetische eigenschappen van een geneesmiddel bijdragen aan een hoge concentratie in de blaas.$$,
